/* ---------- helpers ---------- */
function runText(parent, cx, cyTop, parts, size, italic, anchor) {
  var g = parent.group();
  var items = [], x = 0, i;
  for (i = 0; i < parts.length; i++) {
    var p = parts[i];
    var fs = p.sub ? size * 0.68 : size;
    var el = g.text(p.t).font({
      family: p.sans ? SANS : SERIF, size: fs,
      style: (italic && !p.up) ? 'italic' : 'normal', anchor: 'start'
    }).fill(p.fill || C.ink);
    items.push({ el: el, sub: p.sub, w: el.bbox().width });
  }
  for (i = 0; i < items.length; i++) {
    items[i].el.move(x, items[i].sub ? size * 0.30 : 0);
    x += items[i].w;
  }
  var dx = (anchor === 'start') ? 0 : (anchor === 'end' ? -x : -x / 2);
  g.translate(cx + dx, cyTop);
  g.__w = x;
  return g;
}

function arrowHead(parent, x, y, dir, s, color) {
  parent.polygon([[x, y], [x - s * 0.45, y - dir * s], [x + s * 0.45, y - dir * s]]).fill(color);
}

function halo(t) {
