  var refPath = 'M' + RX + ',' + yR + ' L' + RX + ',' + TOPY;

  p.dyn.path(gasPath).fill('none').stroke({ color: C.gasTint, width: 15, linecap: 'butt', linejoin: 'round' });
  if (yR > TOPY + 1) p.dyn.path(refPath).fill('none').stroke({ color: C.refTint, width: 15, linecap: 'butt' });
  var merc = p.dyn.path(merPath).fill('none').stroke({ color: C.merc, width: 15, linecap: 'butt', linejoin: 'round' });
  p.dyn.line(LX - 7.5, yL, LX + 7.5, yL).stroke({ color: C.mercDark, width: 1.2 });
  p.dyn.line(RX - 7.5, yR, RX + 7.5, yR).stroke({ color: C.mercDark, width: 1.2 });

