    .on('mousemove', function (e) { showTooltip('Mercury (\u03c1 = 13.6 g/cm\u00b3). Height difference h = ' + Math.round(h) + ' mm Hg', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('The mercury column', 'Mercury slides until the pressures pushing down on the two arms are equal at the lowest mercury surface. Total mercury is conserved, so whatever one arm drops the other rises \u2014 the height difference h is the whole measurement.'); });

  /* meniscus level rules */
