function renderPanels() { for (var i = 0; i < panels.length; i++) drawPanel(panels[i]); }

function applyOpacity() {
  for (var i = 0; i < panels.length; i++) {
    var p = panels[i];
    p.active = (cfg !== 'all') && (cfg === p.kind);
    p.g.opacity((cfg === 'all' || cfg === p.kind) ? 1 : 0.18);
  }
}

/* ---------- tween ---------- */
function startTween() { if (!tweening) { tweening = true; requestAnimationFrame(tick); } }
function tick() {
  var keys = ['Pclosed', 'Plow', 'Phigh'], moving = false;
  for (var i = 0; i < keys.length; i++) {
    var k = keys[i], dd = tgt[k] - st[k];
    if (Math.abs(dd) > 0.5) { st[k] += dd * 0.25; moving = true; } else { st[k] = tgt[k]; }
  }
  renderPanels();
  if (moving) requestAnimationFrame(tick); else tweening = false;
}

/* ---------- controls ---------- */
function setSlider(v) {
  var s = document.getElementById('gasPressureInput');
  var o = document.getElementById('gasPressureVal');
  if (s) s.value = v;
  if (o) o.value = v;
}

function update_gasPressure(v) {
  if (cfg === 'closed') { tgt.Pclosed = v; }
  else if (cfg === 'low') {
    if (v > PATM) { cfg = 'high'; document.getElementById('configurationInput').value = 'high'; tgt.Phigh = v; }
    else { tgt.Plow = v; }
  } else if (cfg === 'high') {
    if (v < PATM) { cfg = 'low'; document.getElementById('configurationInput').value = 'low'; tgt.Plow = v; }
    else { tgt.Phigh = v; }
  } else {
    tgt.Pclosed = v;
    if (v < PATM) tgt.Plow = v; else if (v > PATM) tgt.Phigh = v;
  }
  applyOpacity(); startTween();
}

function update_configuration(val) {
  cfg = val;
  var v = (val === 'low') ? tgt.Plow : (val === 'high') ? tgt.Phigh : tgt.Pclosed;
  setSlider(Math.round(v));
  applyOpacity(); startTween();
}

function trigger_showDerivation() {
  var anyOff = false, i;
  for (i = 0; i < panels.length; i++) if (!panels[i].showDeriv) anyOff = true;
  for (i = 0; i < panels.length; i++) panels[i].showDeriv = anyOff;
  document.getElementById('derivBtn').textContent = anyOff ? 'Hide derivation boxes' : 'Show derivation boxes';
  renderPanels();
}

