// @FIGURE_CODE_BEGIN
var mDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
mDraw.viewbox(0, 0, 1240, 500);
mDraw.rect(1240, 500).fill('#ffffff');

var C = {
  glass: '#b9c8d6', glassIn: '#f4f8fa',
  gasTint: '#e9dff1', refTint: '#dfe8ef',
  mercFlat: '#8c8c8c', mercLite: '#bdbdbd',
  bulb: '#e6dcef', bulbLine: '#9a93a4', ink: '#141414'
};
var SANS = "Helvetica Neue, Helvetica, Arial, sans-serif";
var SERIF = "Georgia, 'Times New Roman', serif";

var mercGrad = mDraw.gradient('linear', function (add) {
  add.stop(0, '#6d6d6d'); add.stop(0.28, '#c0c0c0');
  add.stop(0.52, '#949494'); add.stop(1, '#5c5c5c');
}).from(0, 0).to(1, 0);

/* geometry (panel-local) */
var LX = 150, RX = 232, BY = 350, RR = 41, CONN = 118, TOPY = 50;
var L0 = 208, PPT = 0.155, PATM = 760;

/* ---------- helpers ---------- */
function runText(parent, cx, cyTop, parts, size, italic, anchor) {
  var g = parent.group();
  var items = [], x = 0, i;
  for (i = 0; i < parts.length; i++) {
    var p = parts[i];
    var fs = p.sub ? size * 0.7 : size;
    var el = g.text(p.t).font({
      family: p.sans ? SANS : SERIF, size: fs,
      style: (italic && !p.up) ? 'italic' : 'normal', anchor: 'start'
    }).fill(p.fill || C.ink);
    items.push({ el: el, sub: p.sub, w: el.bbox().width });
  }
  for (i = 0; i < items.length; i++) {
    items[i].el.move(x, items[i].sub ? size * 0.30 : 0);
    x += items[i].w;
  }
  var dx = (anchor === 'start') ? 0 : (anchor === 'end' ? -x : -x / 2);
  g.translate(cx + dx, cyTop);
  return g;
}

function arrowHead(parent, x, y, dir, s, color) {
  parent.polygon([[x, y], [x - s * 0.42, y + dir * s], [x + s * 0.42, y + dir * s]]).fill(color);
}

function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}

/* ---------- state ---------- */
var tgt = { Pclosed: 760, Plow: 120, Phigh: 950 };
var st = { Pclosed: 760, Plow: 120, Phigh: 950 };
var cfg = 'all';
var tweening = false;

var panels = [
  {
    kind: 'closed', x: 6,
    eq: [{ t: 'P' }, { t: 'gas', sub: 1 }, { t: ' = h\u03c1g' }],
    deriv: ['At the lowest', 'mercury level:', 'gas side:  P_gas', 'other side: h\u03c1g', '\u21d2 P_gas = h\u03c1g'],
    pop: ['Closed-end manometer', 'The far arm is sealed and evacuated, so nothing pushes down on that mercury column. Balancing pressures at the lowest mercury surface gives P_gas = h\u03c1g: the height difference in millimetres of mercury IS the gas pressure in torr.']
  },
  {
    kind: 'low', x: 418,
    eq: [{ t: 'P' }, { t: 'gas', sub: 1 }, { t: ' = P' }, { t: 'atm', sub: 1 }, { t: ' \u2212 h\u03c1g' }],
    deriv: ['At the lowest', 'mercury level:', 'gas side:  P_gas + h\u03c1g', 'open side: P_atm', '\u21d2 P_gas = P_atm \u2212 h\u03c1g'],
    pop: ['Open end, gas below atmospheric', 'The atmosphere presses on the open arm with 760 torr. Since the gas is weaker, mercury is pushed toward the gas side and stands higher there. Equating pressures at the lowest surface: P_gas + h\u03c1g = P_atm, so P_gas = P_atm \u2212 h\u03c1g.']
  },
  {
    kind: 'high', x: 830,
    eq: [{ t: 'P' }, { t: 'gas', sub: 1 }, { t: ' = P' }, { t: 'atm', sub: 1 }, { t: ' + h\u03c1g' }],
    deriv: ['At the lowest', 'mercury level:', 'gas side:  P_gas', 'open side: P_atm + h\u03c1g', '\u21d2 P_gas = P_atm + h\u03c1g'],
    pop: ['Open end, gas above atmospheric', 'Now the gas wins and shoves mercury up the open arm, so the open column stands higher. Balancing at the lowest surface: P_gas = P_atm + h\u03c1g \u2014 the extra mercury height adds to atmospheric pressure.']
  }
];

/* ---------- static build ---------- */
function buildPanel(p) {
  var g = mDraw.group().translate(p.x, 16);
  p.g = g;
  p.hl = g.group();
  var glass = g.group();
  p.dyn = g.group();
  var fr = g.group();
  p.anno = g.group();

  var ch = 'M80,' + CONN + ' L138,' + CONN + ' Q' + LX + ',' + CONN + ' ' + LX + ',' + (CONN + 13) +
    ' L' + LX + ',' + BY + ' A' + RR + ',' + RR + ' 0 0 0 ' + RX + ',' + BY + ' L' + RX + ',' + TOPY;
  var cap = (p.kind === 'closed') ? 'round' : 'butt';
  glass.path(ch).fill('none').stroke({ color: C.glass, width: 21.5, linecap: cap, linejoin: 'round' });
  glass.path(ch).fill('none').stroke({ color: C.glassIn, width: 15, linecap: cap, linejoin: 'round' });

  /* gas bulb + stopcock */
  var bulb = fr.circle(72).center(46, CONN).fill(C.bulb).stroke({ color: C.bulbLine, width: 1.8 });
  fr.text('Gas').font({ family: SANS, size: 21, anchor: 'middle' }).fill(C.ink).center(46, CONN);
  bulb.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Gas sample: P_gas = ' + Math.round(panelP(p)) + ' torr', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('The unknown gas', 'This bulb holds the gas whose pressure we want. The manometer never reads it directly \u2014 it only balances it against a mercury column, turning a pressure difference into a measurable height h.'); });

  fr.rect(14, 21).center(106, CONN).fill('#dcdce6').stroke({ color: C.bulbLine, width: 1.3 }).radius(2);
  fr.line(106, CONN - 10, 106, CONN - 21).stroke({ color: C.bulbLine, width: 2.6 });
  fr.ellipse(26, 9).center(106, CONN - 24).fill('#eceaf2').stroke({ color: C.bulbLine, width: 1.4 });

  /* end of reference arm + top labels */
  if (p.kind === 'closed') {
    var seal = fr.circle(9).center(RX, TOPY - 5).fill(C.glass).opacity(0.001).css('cursor', 'pointer');
    seal.on('mousemove', function (e) { showTooltip('Sealed tip: the space below is a vacuum, so it pushes down with zero pressure.', e); })
      .on('mouseleave', hideTooltip);
    var t1 = fr.text('Closed end').font({ family: SANS, size: 22, anchor: 'start' }).fill(C.ink).move(268, -12);
    fr.polyline([[264, 0], [248, 20], [241, 40]]).fill('none').stroke({ color: C.ink, width: 1.3 });
    var t2 = fr.text('Vacuum').font({ family: SANS, size: 22, anchor: 'start' }).fill(C.ink).move(268, 20);
    fr.polyline([[264, 32], [252, 68], [242, 104]]).fill('none').stroke({ color: C.ink, width: 1.3 });
    t2.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Evacuated space: pressure = 0, so the mercury feels nothing from above.', e); })
      .on('mouseleave', hideTooltip);
  } else {
    /* flared open lip */
    fr.ellipse(30, 9).center(RX, TOPY).fill(C.refTint).stroke({ color: C.glass, width: 3 });
    var pa = runText(fr, RX, -18, [{ t: 'P' }, { t: 'atm', sub: 1 }], 22, true, 'middle');
    fr.line(RX, 10, RX, TOPY - 14).stroke({ color: '#000', width: 2.2 });
    arrowHead(fr, RX, TOPY - 6, -1, 9, '#000');
    pa.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('The atmosphere presses down on the open arm with P_atm = 760 torr.', e); })
      .on('mouseleave', hideTooltip);
    fr.text('Open end').font({ family: SANS, size: 22, anchor: 'start' }).fill(C.ink).move(266, 30);
    fr.line(262, 42, 246, 50).stroke({ color: C.ink, width: 1.3 });
  }

  /* equation caption */
  var eq = runText(fr, 196, 398, p.eq, 28, true, 'middle');
  eq.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Click: where this equation comes from', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup(p.pop[0], p.pop[1]); });
}

/* ---------- dynamic ---------- */
function panelP(p) { return p.kind === 'closed' ? st.Pclosed : (p.kind === 'low' ? st.Plow : st.Phigh); }
function panelH(p) {
  if (p.kind === 'closed') return Math.max(0, st.Pclosed);
  if (p.kind === 'low') return Math.max(0, PATM - st.Plow);
  return Math.max(0, st.Phigh - PATM);
}

function drawPanel(p) {
  p.dyn.clear(); p.anno.clear(); p.hl.clear();

  if (p.active) {
    p.hl.rect(396, 474).move(2, -14).radius(11)
      .fill({ color: '#eaf4ff', opacity: 0.85 }).stroke({ color: '#5aabf0', width: 2 });
  }

  var h = panelH(p);
  var d = h * PPT;                      /* strictly proportional: no clamp in range */
  var gasHigher = (p.kind === 'low');
  var yL = gasHigher ? L0 - d / 2 : L0 + d / 2;
  var yR = gasHigher ? L0 + d / 2 : L0 - d / 2;
  yL = Math.max(TOPY + 16, Math.min(BY - 12, yL));
  yR = Math.max(TOPY + 16, Math.min(BY - 12, yR));

  /* tinted empty tube */
  var gasPath = 'M80,' + CONN + ' L138,' + CONN + ' Q' + LX + ',' + CONN + ' ' + LX + ',' + (CONN + 13) + ' L' + LX + ',' + yL;
  p.dyn.path(gasPath).fill('none').stroke({ color: C.gasTint, width: 15, linecap: 'butt', linejoin: 'round' });
  if (yR > TOPY + 0.5) {
    p.dyn.line(RX, TOPY, RX, yR).stroke({ color: C.refTint, width: 15, linecap: 'butt' });
  }
  /* glass highlights on the empty parts */
  if (yL > CONN + 20) p.dyn.line(LX - 4.3, CONN + 18, LX - 4.3, yL).stroke({ color: '#ffffff', width: 2.6, opacity: 0.7 });
  if (yR > TOPY + 6) p.dyn.line(RX - 4.3, TOPY + 4, RX - 4.3, yR).stroke({ color: '#ffffff', width: 2.6, opacity: 0.7 });

  /* mercury, cylinder-shaded */
  var m = p.dyn.group();
  m.rect(15, Math.max(0, BY - yL)).move(LX - 7.5, yL).fill(mercGrad);
  m.rect(15, Math.max(0, BY - yR)).move(RX - 7.5, yR).fill(mercGrad);
  m.path('M' + LX + ',' + BY + ' A' + RR + ',' + RR + ' 0 0 0 ' + RX + ',' + BY)
    .fill('none').stroke({ color: C.mercFlat, width: 15, linecap: 'butt' });
  m.path('M' + (LX + 4.5) + ',' + BY + ' A36.5,36.5 0 0 0 ' + (RX - 4.5) + ',' + BY)
    .fill('none').stroke({ color: C.mercLite, width: 3.2, opacity: 0.85, linecap: 'round' });
  m.line(LX - 7.5, yL, LX + 7.5, yL).stroke({ color: '#6f6f6f', width: 1.5 });
  m.line(RX - 7.5, yR, RX + 7.5, yR).stroke({ color: '#6f6f6f', width: 1.5 });

  m.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Mercury (\u03c1 = 13.6 g/cm\u00b3) \u2014 height difference h = ' + Math.round(h) + ' mm Hg', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('The mercury column', 'Mercury slides until the downward pressures on the two arms balance at the lowest mercury surface. Total mercury is conserved, so whatever one arm drops the other rises \u2014 the height difference h is the whole measurement.'); });

  /* meniscus level rules */
  p.anno.line(LX - 26, yL, 266, yL).stroke({ color: '#111', width: 1.1 });
  p.anno.line(RX - 26, yR, 266, yR).stroke({ color: '#111', width: 1.1 });

  /* h arrow: always between the two rules, label beside it */
  var y0 = Math.min(yL, yR), y1 = Math.max(yL, yR), gap = y1 - y0, mid = (y0 + y1) / 2;
  if (gap >= 16) {
    p.anno.line(252, y0, 252, y1).stroke({ color: '#000', width: 1.5 });
    arrowHead(p.anno, 252, y0, 1, 8, '#000');
    arrowHead(p.anno, 252, y1, -1, 8, '#000');
  } else if (gap > 1) {
    p.anno.line(252, y0 - 15, 252, y1 + 15).stroke({ color: '#000', width: 1.5 });
    arrowHead(p.anno, 252, y0, -1, 8, '#000');
    arrowHead(p.anno, 252, y1, 1, 8, '#000');
  }
  var hl = p.anno.text('h').font({ family: SERIF, size: 25, style: 'italic', anchor: 'middle' }).fill('#000');
  halo(hl).center(236, mid);

  var hitTop = Math.min(y0 - 10, mid - 20), hitH = Math.max(gap + 20, 42);
  p.anno.rect(56, hitH).move(226, hitTop).fill('#ffffff').opacity(0.001).css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('h = ' + Math.round(h) + ' mm Hg \u2014 click for the force balance', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      p.showDeriv = !p.showDeriv;
      drawPanel(p);
      showPopup(p.pop[0], p.pop[1]);
    });

  /* derivation callout */
  if (p.showDeriv) {
    p.anno.rect(146, 116).move(0, 188).radius(7)
      .fill({ color: '#fffdf3' }).stroke({ color: '#d7b26b', width: 1.3 });
    for (var i = 0; i < p.deriv.length; i++) {
      p.anno.text(p.deriv[i]).font({ family: SANS, size: 13, anchor: 'start' })
        .fill(i === p.deriv.length - 1 ? '#8a5a00' : '#333').move(8, 195 + i * 20);
    }
  }
}

function updateReadout() {
  var el = document.getElementById('readout');
  if (!el) return;
  el.innerHTML =
    'P<sub>atm</sub> = 760 torr<br>' +
    'closed&nbsp;: P = ' + Math.round(st.Pclosed) + ' torr, h = ' + Math.round(panelH(panels[0])) + ' mm Hg<br>' +
    'open &lt;&nbsp;: P = ' + Math.round(st.Plow) + ' torr, h = ' + Math.round(panelH(panels[1])) + ' mm Hg<br>' +
    'open &gt;&nbsp;: P = ' + Math.round(st.Phigh) + ' torr, h = ' + Math.round(panelH(panels[2])) + ' mm Hg';
}

function renderPanels() {
  for (var i = 0; i < panels.length; i++) drawPanel(panels[i]);
  updateReadout();
}

function applyOpacity() {
  for (var i = 0; i < panels.length; i++) {
