// @FIGURE_CODE_BEGIN
var VW = 1170, VH = 512;
var mDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
mDraw.viewbox(0, 0, VW, VH);
mDraw.rect(VW, VH).fill('#ffffff');

var C = {
  glass: '#b9c8d6', glassIn: '#f4f8fa',
  gasTint: '#e9dff1', refTint: '#dfe8ef',
  mercFlat: '#8c8c8c', mercLite: '#bdbdbd',
  bulb: '#e6dcef', bulbLine: '#9a93a4', ink: '#141414'
};
var SANS = "Helvetica Neue, Helvetica, Arial, sans-serif";
var SERIF = "Georgia, 'Times New Roman', serif";

var mercGrad = mDraw.gradient('linear', function (add) {
  add.stop(0, '#6d6d6d'); add.stop(0.28, '#c0c0c0');
  add.stop(0.52, '#949494'); add.stop(1, '#5c5c5c');
}).from(0, 0).to(1, 0);

/* ---------- panel-local geometry ---------- */
var LX = 112, RX = 180, RR = 34, BY = 400, TOPY = 55, CONN = 115;
var ARROWX = 222, RULEEND = 234, LBLX = 250, PITCH = 388, DY = 12;
var PPT = 0.155, PATM = 760;

/* ---------- helpers ---------- */
/* runText: lays out serif/italic runs with real subscripts.
   part = { t, sub, up, pre (leading gap in em), sans, fill } */
function runText(parent, cx, cyTop, parts, size, italic, anchor) {
  var g = parent.group(), items = [], x = 0, i, p, el, fs;
  for (i = 0; i < parts.length; i++) {
    p = parts[i];
    fs = p.sub ? size * 0.68 : size;
    el = g.text(p.t).font({
      family: p.sans ? SANS : SERIF, size: fs,
      style: (italic && !p.up) ? 'italic' : 'normal', anchor: 'start'
    }).fill(p.fill || C.ink);
    items.push({ el: el, sub: p.sub, pre: p.pre || 0, w: el.bbox().width });
  }
  for (i = 0; i < items.length; i++) {
    x += items[i].pre * size;
    items[i].el.move(x, items[i].sub ? size * 0.30 : 0);
    x += items[i].w;
    if (items[i].sub) x += size * 0.10;   /* advance after a subscript run */
  }
  var dx = (anchor === 'start') ? 0 : (anchor === 'end' ? -x : -x / 2);
  g.translate(cx + dx, cyTop);
  return g;
}

function arrowHead(parent, x, y, dir, s, color) {
  parent.polygon([[x, y], [x - s * 0.42, y + dir * s], [x + s * 0.42, y + dir * s]]).fill(color);
}

function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}

/* ---------- state ---------- */
var tgt = { Pclosed: 760, Plow: 120, Phigh: 950 };
var st = { Pclosed: 760, Plow: 120, Phigh: 950 };
var cfg = 'all';
var tweening = false;

var panels = [
  {
    kind: 'closed', x: 2, base: 250,
    eq: [{ t: 'P' }, { t: 'gas', sub: 1, up: 1 }, { t: '=', pre: 0.30 }, { t: 'h\u03c1g', pre: 0.26 }],
    deriv: ['At lowest Hg level:', 'gas arm:   P_gas', 'closed arm:  h\u03c1g', '\u21d2 P_gas = h\u03c1g'],
    pop: ['Closed-end manometer', 'The far arm is sealed and evacuated, so nothing pushes down on that mercury column. Balancing pressures at the lowest mercury surface gives P_gas = h\u03c1g: the height difference in millimetres of mercury IS the gas pressure in torr.']
  },
  {
    kind: 'low', x: 2 + PITCH, base: 250,
    eq: [{ t: 'P' }, { t: 'gas', sub: 1, up: 1 }, { t: '=', pre: 0.30 }, { t: 'P', pre: 0.26 }, { t: 'atm', sub: 1, up: 1 }, { t: '\u2212', pre: 0.26 }, { t: 'h\u03c1g', pre: 0.24 }],
    deriv: ['At lowest Hg level:', 'gas arm:  P_gas + h\u03c1g', 'open arm:  P_atm', '\u21d2 P_gas = P_atm \u2212 h\u03c1g'],
    pop: ['Open end, gas below atmospheric', 'The atmosphere presses on the open arm with 760 torr. Since the gas is weaker, mercury is pushed toward the gas side and stands higher there. Equating pressures at the lowest surface: P_gas + h\u03c1g = P_atm, so P_gas = P_atm \u2212 h\u03c1g.']
  },
  {
    kind: 'high', x: 2 + 2 * PITCH, base: 185,
    eq: [{ t: 'P' }, { t: 'gas', sub: 1, up: 1 }, { t: '=', pre: 0.30 }, { t: 'P', pre: 0.26 }, { t: 'atm', sub: 1, up: 1 }, { t: '+', pre: 0.26 }, { t: 'h\u03c1g', pre: 0.24 }],
    deriv: ['At lowest Hg level:', 'gas arm:  P_gas', 'open arm:  P_atm + h\u03c1g', '\u21d2 P_gas = P_atm + h\u03c1g'],
    pop: ['Open end, gas above atmospheric', 'Now the gas wins and shoves mercury up the open arm, so the open column stands higher. Balancing at the lowest surface: P_gas = P_atm + h\u03c1g \u2014 the extra mercury height adds to atmospheric pressure.']
  }
];

/* ---------- static build ---------- */
function buildPanel(p) {
  var g = mDraw.group().translate(p.x, DY);
  p.g = g;
  p.hl = g.group();
  var glass = g.group();
  p.dyn = g.group();
  var fr = g.group();
  p.anno = g.group();

  var ch = 'M58,' + CONN + ' L100,' + CONN + ' Q' + LX + ',' + CONN + ' ' + LX + ',' + (CONN + 13) +
    ' L' + LX + ',' + BY + ' A' + RR + ',' + RR + ' 0 0 0 ' + RX + ',' + BY + ' L' + RX + ',' + TOPY;
  var cap = (p.kind === 'closed') ? 'round' : 'butt';
  glass.path(ch).fill('none').stroke({ color: C.glass, width: 22, linecap: cap, linejoin: 'round' });
  glass.path(ch).fill('none').stroke({ color: C.glassIn, width: 15.5, linecap: cap, linejoin: 'round' });

  /* gas bulb + stopcock */
  var bulb = fr.circle(62).center(34, CONN).fill(C.bulb).stroke({ color: C.bulbLine, width: 1.8 });
  fr.text('Gas').font({ family: SANS, size: 24, anchor: 'middle' }).fill(C.ink).center(34, CONN);
  bulb.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Gas sample: P_gas = ' + Math.round(panelP(p)) + ' torr', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('The unknown gas', 'This bulb holds the gas whose pressure we want. The manometer never reads it directly \u2014 it only balances it against a mercury column, turning a pressure difference into a measurable height h.'); });

  fr.rect(13, 20).center(82, CONN).fill('#dcdce6').stroke({ color: C.bulbLine, width: 1.3 }).radius(2);
  fr.line(82, CONN - 9, 82, CONN - 20).stroke({ color: C.bulbLine, width: 2.6 });
  fr.ellipse(24, 8).center(82, CONN - 23).fill('#eceaf2').stroke({ color: C.bulbLine, width: 1.4 });

  /* far-arm end + labels */
  if (p.kind === 'closed') {
    var seal = fr.circle(14).center(RX, TOPY - 4).fill('#fff').opacity(0.001).css('cursor', 'pointer');
    seal.on('mousemove', function (e) { showTooltip('Sealed tip: the space below is a vacuum, so it pushes down with zero pressure.', e); })
      .on('mouseleave', hideTooltip);
    fr.text('Closed end').font({ family: SANS, size: 26, anchor: 'start' }).fill(C.ink).move(LBLX, 2);
    fr.polyline([[LBLX - 5, 18], [212, 34], [192, 52]]).fill('none').stroke({ color: C.ink, width: 1.2 });
    var t2 = fr.text('Vacuum').font({ family: SANS, size: 26, anchor: 'start' }).fill(C.ink).move(LBLX, 36);
    fr.polyline([[LBLX - 5, 52], [214, 76], [196, 100]]).fill('none').stroke({ color: C.ink, width: 1.2 });
    t2.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Evacuated space: pressure = 0, so the mercury feels nothing from above.', e); })
      .on('mouseleave', hideTooltip);
  } else {
    fr.ellipse(30, 9).center(RX, TOPY).fill(C.refTint).stroke({ color: C.glass, width: 3 });
    var pa = runText(fr, RX, -6, [{ t: 'P' }, { t: 'atm', sub: 1, up: 1 }], 26, true, 'middle');
    fr.line(RX, 26, RX, TOPY - 16).stroke({ color: '#000', width: 2.2 });
    arrowHead(fr, RX, TOPY - 7, -1, 9, '#000');
    pa.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('The atmosphere presses down on the open arm with P_atm = 760 torr.', e); })
      .on('mouseleave', hideTooltip);
    fr.text('Open end').font({ family: SANS, size: 26, anchor: 'start' }).fill(C.ink).move(LBLX, 42);
    fr.line(LBLX - 5, 56, 198, 60).stroke({ color: C.ink, width: 1.2 });
  }

  /* equation caption */
  var eq = runText(fr, 170, 452, p.eq, 36, true, 'middle');
  eq.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Click: where this equation comes from', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup(p.pop[0], p.pop[1]); });
}

/* ---------- dynamic ---------- */
function panelP(p) { return p.kind === 'closed' ? st.Pclosed : (p.kind === 'low' ? st.Plow : st.Phigh); }
function panelH(p) {
  if (p.kind === 'closed') return Math.max(0, st.Pclosed);
  if (p.kind === 'low') return Math.max(0, PATM - st.Plow);
  return Math.max(0, st.Phigh - PATM);
}

function drawPanel(p) {
  p.dyn.clear(); p.anno.clear(); p.hl.clear();

  if (p.active) {
    p.hl.rect(384, 496).move(-4, -8).radius(11)
      .fill({ color: '#eaf4ff', opacity: 0.85 }).stroke({ color: '#5aabf0', width: 2 });
  }

  var h = panelH(p);
  var d = h * PPT;                       /* strictly proportional */
  var gasHigher = (p.kind === 'low');
  var L0 = p.base;
  var yL = gasHigher ? L0 - d / 2 : L0 + d / 2;
  var yR = gasHigher ? L0 + d / 2 : L0 - d / 2;
  yL = Math.max(TOPY + 18, Math.min(BY - 14, yL));
  yR = Math.max(TOPY + 18, Math.min(BY - 14, yR));

  /* tinted empty tube */
  var gasPath = 'M58,' + CONN + ' L100,' + CONN + ' Q' + LX + ',' + CONN + ' ' + LX + ',' + (CONN + 13) + ' L' + LX + ',' + yL;
  p.dyn.path(gasPath).fill('none').stroke({ color: C.gasTint, width: 15.5, linecap: 'butt', linejoin: 'round' });
  if (yR > TOPY + 0.5) {
    p.dyn.line(RX, TOPY, RX, yR).stroke({ color: C.refTint, width: 15.5, linecap: 'butt' });
  }
  if (yL > CONN + 20) p.dyn.line(LX - 4.3, CONN + 18, LX - 4.3, yL).stroke({ color: '#ffffff', width: 2.6, opacity: 0.7 });
  if (yR > TOPY + 6) p.dyn.line(RX - 4.3, TOPY + 4, RX - 4.3, yR).stroke({ color: '#ffffff', width: 2.6, opacity: 0.7 });

  /* mercury */
  var m = p.dyn.group();
  m.rect(15.5, Math.max(0, BY - yL)).move(LX - 7.75, yL).fill(mercGrad);
  m.rect(15.5, Math.max(0, BY - yR)).move(RX - 7.75, yR).fill(mercGrad);
  m.path('M' + LX + ',' + BY + ' A' + RR + ',' + RR + ' 0 0 0 ' + RX + ',' + BY)
    .fill('none').stroke({ color: C.mercFlat, width: 15.5, linecap: 'butt' });
  m.path('M' + (LX + 4.5) + ',' + BY + ' A29.5,29.5 0 0 0 ' + (RX - 4.5) + ',' + BY)
    .fill('none').stroke({ color: C.mercLite, width: 3.2, opacity: 0.85, linecap: 'round' });
  m.line(LX - 7.75, yL, LX + 7.75, yL).stroke({ color: '#6f6f6f', width: 1.5 });
  m.line(RX - 7.75, yR, RX + 7.75, yR).stroke({ color: '#6f6f6f', width: 1.5 });

  m.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Mercury (\u03c1 = 13.6 g/cm\u00b3) \u2014 height difference h = ' + Math.round(h) + ' mm Hg', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('The mercury column', 'Mercury slides until the downward pressures on the two arms balance at the lowest mercury surface. Total mercury is conserved, so whatever one arm drops the other rises \u2014 the height difference h is the whole measurement.'); });

  /* meniscus level rules: thin, shorter than the h arrow's weight */
  p.anno.line(LX - 16, yL, RULEEND, yL).stroke({ color: '#222', width: 1 });
  p.anno.line(RX - 16, yR, RULEEND, yR).stroke({ color: '#222', width: 1 });

  /* h arrow + label (label moves outboard when the gap is small) */
  var y0 = Math.min(yL, yR), y1 = Math.max(yL, yR), gap = y1 - y0, mid = (y0 + y1) / 2;
  var lblX = 204;
  if (gap >= 40) {
    p.anno.line(ARROWX, y0, ARROWX, y1).stroke({ color: '#000', width: 2 });
    arrowHead(p.anno, ARROWX, y0, 1, 9, '#000');
    arrowHead(p.anno, ARROWX, y1, -1, 9, '#000');
  } else {
    lblX = 254;
    p.anno.line(ARROWX, y0 - 17, ARROWX, y1 + 17).stroke({ color: '#000', width: 2 });
    arrowHead(p.anno, ARROWX, y0, -1, 9, '#000');
    arrowHead(p.anno, ARROWX, y1, 1, 9, '#000');
    if (gap > 2) p.anno.line(ARROWX + 6, mid, lblX - 12, mid).stroke({ color: '#000', width: 0.9 });
  }
  var hl = p.anno.text('h').font({ family: SERIF, size: 32, style: 'italic', anchor: 'middle' }).fill('#000');
  halo(hl).center(lblX, mid);

  var hitTop = Math.min(y0 - 12, mid - 24), hitH = Math.max(gap + 24, 48);
  p.anno.rect(88, hitH).move(192, hitTop).fill('#ffffff').opacity(0.001).css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('h = ' + Math.round(h) + ' mm Hg \u2014 click for the force balance', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      p.showDeriv = !p.showDeriv;
      drawPanel(p);
      showPopup(p.pop[0], p.pop[1]);
    });

  /* derivation callout, parked in the label whitespace */
  if (p.showDeriv) {
    p.anno.rect(156, 108).move(238, 168).radius(7)
      .fill({ color: '#fffdf3' }).stroke({ color: '#d7b26b', width: 1.3 });
    for (var i = 0; i < p.deriv.length; i++) {
      p.anno.text(p.deriv[i]).font({ family: SANS, size: 12.5, anchor: 'start' })
        .fill(i === p.deriv.length - 1 ? '#8a5a00' : '#333').move(246, 175 + i * 24);
    }
  }
}

function updateReadout() {
  var el = document.getElementById('readout');
  if (!el) return;
  el.innerHTML =
    'P<sub>atm</sub> = 760 torr<br>' +
    'closed&nbsp;: P = ' + Math.round(st.Pclosed) + ' torr, h = ' + Math.round(panelH(panels[0])) + ' mm Hg<br>' +
    'open &lt;&nbsp;: P = ' + Math.round(st.Plow) + ' torr, h = ' + Math.round(panelH(panels[1])) + ' mm Hg<br>' +
    'open &gt;&nbsp;: P = ' + Math.round(st.Phigh) + ' torr, h = ' + Math.round(panelH(panels[2])) + ' mm Hg';
}

function renderPanels() {
  for (var i = 0; i < panels.length; i++) drawPanel(panels[i]);
  updateReadout();
}

function applyOpacity() {
  for (var i = 0; i < panels.length; i++) {
    var p = panels[i];
    p.active = (cfg !== 'all') && (cfg === p.kind);
    p.g.opacity((cfg === 'all' || cfg === p.kind) ? 1 : 0.18);
  }
}

/* ---------- tween ---------- */
function startTween() { if (!tweening) { tweening = true; requestAnimationFrame(tick); } }
function tick() {
  var keys = ['Pclosed', 'Plow', 'Phigh'], moving = false;
  for (var i = 0; i < keys.length; i++) {
    var k = keys[i], dd = tgt[k] - st[k];
    if (Math.abs(dd) > 0.5) { st[k] += dd * 0.25; moving = true; } else { st[k] = tgt[k]; }
  }
  renderPanels();
  if (moving) requestAnimationFrame(tick); else tweening = false;
}

/* ---------- controls ---------- */
function setSlider(v) {
  var s = document.getElementById('gasPressureInput');
  var o = document.getElementById('gasPressureVal');
  if (s) s.value = v;
  if (o) o.value = v;
}

function update_gasPressure(v) {
  if (cfg === 'closed') { tgt.Pclosed = v; }
  else if (cfg === 'low') {
    if (v > PATM) { cfg = 'high'; document.getElementById('configurationInput').value = 'high'; tgt.Phigh = v; }
    else { tgt.Plow = v; }
  } else if (cfg === 'high') {
    if (v < PATM) { cfg = 'low'; document.getElementById('configurationInput').value = 'low'; tgt.Plow = v; }
    else { tgt.Phigh = v; }
  } else {
    tgt.Pclosed = v;
    if (v < PATM) tgt.Plow = v; else if (v > PATM) tgt.Phigh = v;
  }
  applyOpacity(); startTween();
}

function update_configuration(val) {
  cfg = val;
  var v = (val === 'low') ? tgt.Plow : (val === 'high') ? tgt.Phigh : tgt.Pclosed;
  setSlider(Math.round(v));
  applyOpacity(); startTween();
}

function trigger_showDerivation() {
  var anyOff = false, i;
  for (i = 0; i < panels.length; i++) if (!panels[i].showDeriv) anyOff = true;
  for (i = 0; i < panels.length; i++) panels[i].showDeriv = anyOff;
  document.getElementById('derivBtn').textContent = anyOff ? 'Hide derivation boxes' : 'Show derivation boxes';
  renderPanels();
}

/* ---------- demo steps ---------- */
var steps = [
  { t: 'Three cases, one instrument', n: 'All three drawings are the same U-tube of mercury connected to a gas bulb; only the far arm and the liquid levels differ. Each configuration carries its own equation for P_gas.', cfg: 'all', P: 760 },
  { t: 'Closed end: mercury measures pressure outright', n: 'With the far arm sealed and evacuated, nothing pushes back on the mercury from above, so the entire height difference h is produced by the gas alone: P_gas = h\u03c1g.', cfg: 'closed', P: 400 },
  { t: 'Raise the gas pressure', n: 'Drag P_gas upward and watch h grow in exact proportion. In a closed-end manometer, h in millimetres of mercury IS the gas pressure in torr.', cfg: 'closed', P: 1000 },
  { t: 'Open end, gas below atmospheric', n: 'Now the far arm feels P_atm pushing down. Because the gas is weaker, atmospheric pressure drives mercury toward the gas side, leaving that column higher: P_gas = P_atm \u2212 h\u03c1g.', cfg: 'low', P: 600 },
  { t: 'Open end, gas above atmospheric', n: 'Push P_gas past 760 torr and the columns swap: the gas shoves mercury up the open arm, so the extra height adds to atmospheric pressure, giving P_gas = P_atm + h\u03c1g.', cfg: 'high', P: 950 },
  { t: 'Where the equations come from', n: 'Click the h arrow to see the force balance at the lowest mercury level \u2014 every one of the three formulas is just "pressure down on the left = pressure down on the right" rearranged.', cfg: 'all', P: 950 }
];
var stepI = 0;

function applyStep(i) {
  stepI = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepI];
  cfg = s.cfg;
  document.getElementById('configurationInput').value = cfg;
  setSlider(s.P);
  update_gasPressure(s.P);
  document.getElementById('demoNarration').textContent = s.t + ' \u2014 ' + s.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepI + 1) + ' / ' + steps.length;
}
function nextStep() { applyStep(stepI + 1); }
function prevStep() { applyStep(stepI - 1); }

/* ---------- init ---------- */
for (var i = 0; i < panels.length; i++) buildPanel(panels[i]);
applyOpacity();
renderPanels();
applyStep(0);

window.__markRendered();
